/* ============ MY EVC — v9 : espace étudiant selon la charte UI ============ */
const UVS_OLD = {}; ['e-seances'].forEach(id => UVS_OLD[id] = VIEWS[id].render);
uReg('mtab','sview','tgrp','ptab','nf','cf','ofilt','eqf');

/* ----- Données dérivées ----- */
const uAvg = fs => { const e = S.st.evals.filter(x=>fs.includes(x.f) && x.note!=null); if (!e.length) return null; const s = e.reduce((a,x)=>a+x.note*x.coef,0), c = e.reduce((a,x)=>a+x.coef,0); return (s/c).toFixed(1).replace('.',','); };
const uPres = fs => Math.round(fs.reduce((a,f)=>a+F[f].presence,0)/fs.length);
const uOpenTodos = fs => S.st.todos.filter(t=>fs.includes(t.f) && ['afaire','encours','reprendre'].includes(t.status)).sort((a,b)=>a.due-b.due);
const uNextSeances = fs => S.st.seances.filter(x=>fs.includes(x.f) && (x.d>0 || (x.d===0 && x.e>TODAY.getHours()))).sort((a,b)=>a.d-b.d||a.h-b.h);
const uFShort = f => ({DG:'Design graphique', CM:'Community management', GIA:'Bureautique'})[f];
const uDueDate = d => fmtD(addDays(d),{weekday:'long',day:'numeric',month:'long'});
const uPayDate = s => { const [d,m,y] = s.split('/').map(Number); return new Date(y,m-1,d); };
const uHoursTo = x => Math.round((addDays(x.d, 0).setHours(Math.floor(x.h), (x.h%1)*60) - TODAY)/3600000);
const uTrainerOf = f => F[f].trainer;

/* ----- Tableau de bord ----- */
view('e-dashboard','etu','Tableau de bord','fa-house-chimney', () => {
  const st = S.st, s = st.student, fs = vf(), ps = payState();
  const done = fs.reduce((a,f)=>a+F[f].sessions.done,0), total = fs.reduce((a,f)=>a+F[f].sessions.total,0);
  const pct = Math.round(fs.reduce((a,f)=>a+prog(f),0)/fs.length), pres = uPres(fs), avg = uAvg(fs);
  const open = uOpenTodos(fs), next = uNextSeances(fs), notes = st.evals.filter(e=>fs.includes(e.f) && e.note!=null).sort((a,b)=>b.d-a.d);
  const watch = S.videos.find(v=>fs.includes(v.f) && v.pub && (st.tv.prog[v.id]||0)>0 && st.tv.prog[v.id]<1), now = next[0];
  const cta = now && now.d===0 && now.mode==='Virtuel' ? `<button class="btn btn-primary" data-act="seance" data-id="${now.id}"><i class="fa-solid fa-video"></i>Rejoindre la séance ${now.n}</button>`
    : watch ? `<button class="btn btn-primary" data-act="tv-resume" data-id="${watch.id}"><i class="fa-solid fa-play"></i>Reprendre la séance ${watch.n||''}</button>` : `<button class="btn btn-primary" data-go="e-formations">Voir ma formation</button>`;
  const sub = fs.length>1 ? fs.map(uFShort).join(' · ') + ` · ${done} séances sur ${total}` : `${fname(fs[0])} · Séance ${Math.min(chaptersDone(fs[0])+1, chapters(fs[0]))} sur ${chapters(fs[0])}`;
  const paidN = ps.sched.filter(x=>x.status==='Payé').length;
  const notesN = st.evals.filter(e=>fs.includes(e.f) && e.note!=null).length;
  return `${commBanner()}${onbCard()}
  <section class="hero2">${motif('h2-motif')}${star('h2-star')}
    <div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div style="min-width:0;flex:1 1 420px"><div class="h2-k">Bonjour ${esc(s.first)},</div><h2>Vous avez parcouru ${pct} % de ${fs.length>1?'vos formations':'votre formation'}</h2><p>${esc(sub)}</p></div><div class="hero-cta">${cta}</div></div>
    <div class="mt-4" style="max-width:800px">${frise([{l:'Préinscription'},{l:'Inscription'},{l:'Formation'},{l:'Évaluations'},{l:'Certification'}], 2, {dark:true})}</div>
  </section>
  <div class="m-tiles d-md-none">${[['e-todo','fa-file-lines','Travaux',open.length],['e-evaluations','fa-chart-column','Notes',0],['e-messagerie','fa-message','Messages',2],['e-insertion','fa-briefcase','Carrière',0]].map(([id,ic,l,n])=>`<a href="#${id}" class="m-tile"><span class="mt-i"><i class="fa-solid ${ic}"></i>${n?`<span class="bn-count">${n}</span>`:''}</span>${l}</a>`).join('')}</div>
  <div class="grid g-kpi mt-4">
    ${uKpi('Assiduité', `${pres} %`, pres>=80?'Objectif 80 % atteint':'Sous le seuil de 80 %', 'fa-clipboard-check', 'ok', pres>=80?'ok':'bad')}
    ${uKpi('Évaluations validées', `${st.evals.filter(e=>fs.includes(e.f) && e.note!=null && e.note>=10).length} / ${st.evals.filter(e=>fs.includes(e.f)).length}`, `${notesN} évaluation${notesN>1?'s':''} corrigée${notesN>1?'s':''} · sans notation`, 'fa-chart-column', 'lav')}
    ${uKpi('Travaux à rendre', open.length, open[0]?`Le plus proche : ${dueTxt(open[0].due).toLowerCase()}`:'Rien en attente', 'fa-file-lines', 'warn', open[0]?(open[0].due<0?'bad':'warn'):'ok')}
    ${uKpi('Paiements', `${paidN} / ${ps.sched.length}`, ps.next?`Prochain le ${fmtDM(uPayDate(ps.next.due))}`:'Formation soldée', 'fa-credit-card', 'c')}
  </div>
  <div class="u-grid u-1-1 mt-4">
    ${uCard('Prochaines séances', next.length ? next.slice(0,3).map(x=>`<div class="lrow clickable" data-act="seance" data-id="${x.id}">${uDbox(dateOf(x))}<div class="lr-m"><div class="lr-t">${esc(x.t)}</div><div class="lr-s">${uH(hrs(x))} · ${x.mode==='Virtuel'?'En ligne':'Présentiel'} · ${uTrainerOf(x.f)}${fs.length>1?` · ${x.f}`:''}</div></div>${x.mode==='Virtuel'?pill('Visio','info'):pill('Présentiel','mute')}</div>`).join('') : uEmpty('Aucune séance programmée','Votre planning apparaîtra ici.'), {tools:`<a class="link-u" href="#e-seances">Voir le planning</a>`})}
    ${uCard('Travaux à rendre', (open.length ? open.slice(0,2).map(t=>`<div class="box-row d-block"><div class="d-flex justify-content-between gap-2 align-items-start"><div style="min-width:0"><div class="fw-sb">${esc(t.t)}</div><div class="small muted">${uFShort(t.f)} · ${esc(t.type)}</div></div>${t.status==='reprendre'?pill('À reprendre','bad'):pill(dueTxt(t.due), dueTone(t.due))}</div><button class="btn btn-ghost btn-sm mt-3" data-act="todo" data-id="${t.id}">${t.status==='afaire'?'Lire et démarrer':'Déposer mon travail'}</button></div>`).join('') : uEmpty('Aucun travail à rendre','Vous êtes à jour. Les nouveaux travaux apparaîtront ici.',`<a class="btn btn-ghost btn-sm" href="#e-seances">Voir mes séances</a>`))
      + (ps.next ? `<div class="alert-strip as-warn slim mt-3"><i class="fa-solid fa-clock"></i><span class="flex-grow-1"><b>${esc(ps.next.kind==='dep'?'Inscription':'Solde')} ${ps.next.f}</b> de ${fcfa(ps.next.amount-ps.next.paid)} attendu le ${fmtDM(uPayDate(ps.next.due))}.</span><button class="link-u" data-act="go-pay">Payer</button></div>` : ''), {tools:`<a class="link-u" href="#e-todo">Tous les travaux</a>`})}
  </div>
  ${notes.length ? uCard('Dernières appréciations', `<div class="u-grid" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px">${notes.slice(0,4).map(e=>`<div class="lrow m-0"><div class="lr-m"><div class="lr-t">${esc(e.t.split(' — ')[1]||e.t)}</div><div class="lr-s">${esc(e.type)}</div></div>${uAppPill(e.note)}</div>`).join('')}</div>`, {cls:'mt-4', tools:`<a class="link-u" href="#e-evaluations">Mes évaluations</a>`}) : ''}`;
}, () => { if (!S.st.onb.hidden && !S.st.onb.tourSeen) { S.st.onb.tourSeen = true; setTimeout(()=>{ if (S.view==='e-dashboard') tourStart(); }, 900); } });
ACT['go-pay'] = () => go('e-paiements');

/* ----- Ma formation ----- */
view('e-formations','etu','Ma formation','fa-book-open', () => {
  const fs = vf(); if (!fs.includes(S.ui.ftab)) S.ui.ftab = fs[0]; const f = S.ui.ftab, Fx = S.formations[f], tab = S.ui.mtab || 'seances';
  const cur = Fx.prog.find(y=>!y.done);
  const head = `${fs.length>1?`<div class="mb-3">${uSeg(fs.map(x=>[x, `${x} · ${uFShort(x)}`]), f, 'ftab', {soft:true, attr:'f'})}</div>`:''}
  <section class="panel f-head c-${f}"><div class="fh-art">${motif('fh-motif')}${star('fh-star')}</div><div class="fh-b"><div class="d-flex gap-2 flex-wrap mb-2">${pill('En cours','ok')}${pill(S.st.student.session.replace(' — Abidjan',''),'mute')}</div><h2 class="fh-t">${esc(Fx.name)}</h2><div class="muted">${Fx.prog.length} séances · ${Fx.months} mois · ${esc(Fx.format.split(':')[0])} · Formateur référent : ${Fx.trainer}</div><div class="d-flex align-items-center gap-3 mt-3 flex-wrap"><div style="flex:1 1 260px">${uBar(prog(f),'lg')}</div><b class="num">${prog(f)} %</b><span class="muted small">${chaptersDone(f)} séances sur ${chapters(f)}</span></div></div></section>`;
  let body = '';
  if (tab==='seances') body = Fx.prog.map(x=>{ const st = S.st.seances.find(y=>y.f===f && y.n===x.n), isCur = x===cur, v = S.videos.find(y=>y.f===f && y.n===x.n && y.pub);
    const right = x.done ? (v ? pill('Replay disponible','ok') : pill('Terminé','ok')) : isCur ? pill(x.d===0?"Aujourd'hui":x.d===1?'Demain':'Prochaine','acc') : pill('À venir','grey');
    return `<div class="box-row clickable ${isCur?'sel':''} ${!x.done&&!isCur?'dim':''}" data-act="u-seance" data-id="${st.id}" role="button" tabindex="0"><span class="nsq ${x.done?'done':isCur?'cur':''}">${x.done?'<i class="fa-solid fa-check"></i>':x.n}</span><div class="lr-m"><div class="fw-sb">${esc(x.t)}</div><div class="small muted">Séance ${x.n} · ${fmtD(addDays(x.d),{day:'numeric',month:'short'})} · ${uH(x.hl)} · ${modeLbl(x.mode).toLowerCase()}</div></div>${right}</div>`; }).join('');
  if (tab==='ress') { const lib = libFor([f]); body = `<div class="panel p-0">${lib.slice(0,8).map(libRow).join('')}</div><div class="mt-3"><a class="link-u" href="#e-bibliotheque">Ouvrir la bibliothèque complète (${lib.length} ressources)</a></div>`; }
  if (tab==='ann') { const L = S.st.notifs.filter(n=>['Annonces','Communiqués'].includes(n.cat) && (!n.f || n.f===f)); body = L.length ? L.map(n=>`<div class="box-row clickable" data-act="n-read" data-id="${n.id}"><span class="nsq cor"><i class="fa-solid fa-bullhorn"></i></span><div class="lr-m"><div class="fw-sb">${esc(n.t)}</div><div class="small muted">${n.d}</div></div><i class="fa-solid fa-chevron-right muted"></i></div>`).join('') : uEmpty('Aucune annonce','Les annonces de votre formation apparaîtront ici.'); }
  if (tab==='projet') { const r = S.st.reports[f], dg = f==='DG';
    body = `<div class="u-grid u-1-1">${dg ? `<div class="box-row d-block"><div class="small-caps mb-2">Studio Creative · édition ${S.st.studio.edition}</div><h3 class="h3 mb-1">${esc(S.st.studio.title)}</h3><p class="muted small mb-3">${esc(S.st.studio.theme)}</p>${S.st.studio.registered?pill(S.st.studio.submitted?'Projet soumis':'Inscrite','ok'):pill('Inscriptions ouvertes','info')}<div class="mt-3"><a class="btn btn-ghost btn-sm" href="#e-projets">Ouvrir mes projets</a></div></div>`
      : `<div class="box-row d-block"><div class="small-caps mb-2">RECO 60 · projet professionnel</div><h3 class="h3 mb-1">${esc(S.st.reco[f].name)}</h3><div class="d-flex align-items-center gap-3 my-3"><div class="flex-grow-1">${uBar(recoDay(f)/60*100,'cor')}</div><b>Jour ${recoDay(f)} / 60</b></div><a class="btn btn-ghost btn-sm" href="#e-projets">Ouvrir mon RECO 60</a></div>`}
      <div class="box-row d-block"><div class="small-caps mb-2">Rapport de fin de formation</div><h3 class="h3 mb-1">Statut : ${esc(r.st)}</h3><p class="muted small mb-3">${r.versions.length} version${r.versions.length>1?'s':''} déposée${r.versions.length>1?'s':''}${r.comments.length?` · ${r.comments.length} commentaire(s) du formateur`:''}.</p><a class="btn btn-ghost btn-sm" href="#e-rapports">Gérer mon rapport</a></div></div>`; }
  const team = [[Fx.trainer,'Formateur référent'],[Fx.trainer2,'Formateur · '+uFShort(f)],['Service pédagogique','Questions administratives']];
  const lib = libFor([f]).filter(r=>r.f===f).slice(0,3);
  return `${head}<div class="u-grid u-2-1 mt-4"><div>${uTabs([['seances','Séances'],['ress','Ressources'],['ann','Annonces'],['projet','Projet de fin de formation']], tab, 'u-mtab')}<div>${body}</div></div>
  <div class="stack">${uCard('Équipe pédagogique', team.map(([n,r])=>`<div class="d-flex align-items-center gap-3 py-2">${uIni(n)}<div class="lr-m"><div class="fw-sb">${esc(n)}</div><div class="small muted">${r}</div></div><button class="btn btn-quiet btn-sm btn-icon" data-act="msg-new" aria-label="Écrire à ${esc(n)}"><i class="fa-solid fa-message"></i></button></div>`).join(''))}
  ${uCard('Bibliothèque', lib.length ? `<div class="lib-rows-flush">${lib.map(libRow).join('')}</div>` : '<p class="muted small mb-0">Aucune ressource.</p>', {tools:`<a class="btn btn-quiet btn-sm" href="#e-bibliotheque">Tout voir</a>`})}</div></div>`;
});
VIEWS['e-formations'].crumbTail = 'Formations';
ACT['u-seance'] = el => uGo('e-seance', {seance: el.dataset.id});

/* ----- Détail d'une séance (replay, supports, notes personnelles) ----- */
let UP_T = null;
const UP_CH = t => [['00:00','Introduction et rappel de la séance précédente'],['12:40','Notions clés : '+t],['38:15','Démonstration pas à pas'],['1:05:30','Atelier pratique en petits groupes'],['1:41:00','Consignes pour la séance suivante']];
const upSec = s => s.split(':').map(Number).reduce((a,x)=>a*60+x,0);
view('e-seance','etu','Séance','fa-calendar-days', () => {
  const x = S.st.seances.find(s=>s.id===S.ui.seance) || S.st.seances.find(s=>s.done) , virt = x.mode==='Virtuel', dur = 6852;
  S.st.up = S.st.up || {}; const pos = S.st.up[x.id] || 0; S.st.pnotes = S.st.pnotes || {};
  const left = x.done ? `<div class="u-player ${S.ui.upOn?'playing':''}" id="u-player"><div class="up-screen" data-act="up-play" role="button" aria-label="Lire ou mettre en pause">${motif('up-motif')}${star('up-star')}<span class="up-tag">Replay · 1 h 54</span><span class="up-play"><i class="fa-solid fa-play up-i-play"></i><i class="fa-solid fa-pause up-i-pause"></i></span></div><div class="up-bar"><span id="up-t">${mmss(pos)}</span><div class="up-track" data-act="up-seek"><span id="up-fill" style="width:${pos/dur*100}%"></span></div><span>1:54:12</span></div></div>
    ${uCard('Chapitres', UP_CH(x.t).map(([t,l])=>`<button class="lrow w-100 border-0 text-start clickable ch-row" data-act="up-chap" data-s="${upSec(t)}"><b class="tx-c num" style="width:64px">${t}</b><span class="lr-m fw-sb" style="font-size:14px">${esc(l)}</span></button>`).join(''), {cls:'mt-4'})}
    ${uCard('Compte rendu du formateur', `<p class="mb-0">Nous avons travaillé sur « ${esc(x.t)} » à partir d'exemples concrets, puis chacun a réalisé un exercice guidé. Pour la séance suivante, préparez trois exemples que vous trouvez réussis et expliquez pourquoi.</p>`, {cls:'mt-4'})}`
    : `<div class="hero2"><div class="h2-kc">Séance à venir</div><h2>${esc(x.t)}</h2><p>${fmtD(dateOf(x),{weekday:'long',day:'numeric',month:'long'})} · ${uH(hrs(x))} · ${virt?'en ligne':'présentiel, '+esc(PLACE_EVC)}</p><div class="d-flex gap-2 mt-4 flex-wrap">${virt?`<a class="btn btn-primary" href="https://${esc(x.place)}" target="_blank" rel="noopener"><i class="fa-solid fa-video"></i>Rejoindre la séance</a>`:''}<button class="btn btn-white-line" data-act="u-agenda" data-id="${x.id}">Ajouter à mon agenda</button></div></div>
    ${uCard('À préparer', `<ul class="mb-0 ps-3"><li>Relire le support de la séance précédente</li><li>Installer et ouvrir les logiciels de la séance</li><li>Apporter vos fichiers de travail en cours</li></ul>`, {cls:'mt-4'})}`;
  return `<div class="u-grid u-2-1"><div>${left}</div><div class="stack">
    ${uCard('Informations', `<div class="kv"><span>Date</span><b>${fmtD(dateOf(x),{weekday:'long',day:'numeric',month:'long'})}</b></div><div class="kv"><span>Horaire</span><b>${uH(hrs(x))}</b></div><div class="kv"><span>Formateur</span><b>${uTrainerOf(x.f)}</b></div><div class="kv"><span>Ma présence</span>${x.st==='present'?pill('Présente','ok'):x.st==='retard'?pill('Retard','warn'):x.st==='absent'?pill('Absente','bad'):pill('À venir','grey')}</div>`)}
    ${uCard('Supports de la séance', `<div class="lrow"><span class="ftype">PDF</span><div class="lr-m"><div class="lr-t" style="font-size:14px">Diaporama · séance ${x.n}</div></div><button class="btn btn-quiet btn-sm btn-icon border-0 bg-transparent" data-act="fake-dl" data-n="Diaporama séance ${x.n}"><i class="fa-solid fa-download"></i></button></div><div class="lrow"><span class="ftype">ZIP</span><div class="lr-m"><div class="lr-t" style="font-size:14px">Fichiers d'exercice</div></div><button class="btn btn-quiet btn-sm btn-icon border-0 bg-transparent" data-act="fake-dl" data-n="Exercices séance ${x.n}"><i class="fa-solid fa-download"></i></button></div>`)}
    ${uCard('Mes notes personnelles', `<textarea class="form-control" rows="4" placeholder="Visibles uniquement par vous" data-inp="u-pnote" data-id="${x.id}" aria-label="Mes notes personnelles">${esc(S.st.pnotes[x.id]||'')}</textarea><div class="small muted mt-2" id="pn-saved">${S.st.pnotes[x.id]?'Enregistrées automatiquement':''}</div>`)}
    <a class="link-u" href="#e-formations">‹ Retour à ma formation</a></div></div>`;
}, () => { if (S.ui.upOn) upRun(); });
Object.assign(VIEWS['e-seance'], {parent:'e-formations', title:() => { const x = S.st.seances.find(s=>s.id===S.ui.seance); return x ? esc(x.t) : 'Séance'; }, crumb:() => { const x = S.st.seances.find(s=>s.id===S.ui.seance); return `Espace étudiant <span class="sep">›</span> Ma formation <span class="sep">›</span> Séance ${x?x.n:''}`; }});
function upPaint(){ const x = S.ui.seance, p = S.st.up[x]||0, f = $('#up-fill'), t = $('#up-t'); if (f) f.style.width = (p/6852*100)+'%'; if (t) t.textContent = mmss(p); }
function upRun(){ clearInterval(UP_T); UP_T = setInterval(() => { if (S.view!=='e-seance' || !S.ui.upOn || !$('#u-player')) { clearInterval(UP_T); return; } const x = S.ui.seance; S.st.up[x] = Math.min(6852, (S.st.up[x]||0) + 24); upPaint(); }, 250); }
ACT['up-play'] = () => { S.ui.upOn = !S.ui.upOn; $('#u-player')?.classList.toggle('playing', S.ui.upOn); if (S.ui.upOn) upRun(); };
ACT['up-seek'] = (el, e) => { const r = el.getBoundingClientRect(); S.st.up[S.ui.seance] = Math.round((e.clientX-r.left)/r.width*6852); upPaint(); };
ACT['up-chap'] = el => { S.st.up[S.ui.seance] = +el.dataset.s; upPaint(); if (!S.ui.upOn) ACT['up-play'](); };
ACT['u-agenda'] = () => toast('Séance ajoutée à votre agenda (fichier .ics envoyé par e-mail).','info');
INP['u-pnote'] = el => { S.st.pnotes[el.dataset.id] = el.value; const s = $('#pn-saved'); if (s) s.textContent = 'Enregistrées automatiquement'; };

/* ----- Séances : semaine, liste, présences, rattrapages, replays ----- */
view('e-seances','etu','Séances','fa-calendar-days', () => {
  const fs = vf(), tab = S.ui.sview || 'semaine', all = S.st.seances.filter(x=>fs.includes(x.f));
  const segs = uSeg([['semaine','Semaine'],['liste','Liste'],['pres','Présences'],['ratt','Rattrapages'],['replay','Replays']], tab, 'u-sview');
  if (['pres','ratt','replay'].includes(tab)) { S.ui.stab = tab; return `<div class="mb-4">${segs}</div>${UVS_OLD['e-seances']().replace(/^<ul class="nav nav-tabs[\s\S]*?<\/ul>/,'')}`; }
  if (tab==='liste') { const L = all.filter(x=>x.d>=0).sort((a,b)=>a.d-b.d||a.h-b.h);
    return `<div class="mb-4">${segs}</div>${uCard('Prochaines séances', L.map(x=>`<div class="lrow clickable" data-act="u-sel" data-id="${x.id}">${uDbox(dateOf(x))}<div class="lr-m"><div class="lr-t">${esc(x.t)}</div><div class="lr-s">${x.f} · Séance ${x.n} · ${uH(hrs(x))} · ${uTrainerOf(x.f)}</div></div>${x.mode==='Virtuel'?pill('Visio','info'):pill('Présentiel','mute')}</div>`).join('') || uEmpty('Aucune séance à venir'))}`; }
  const wk = S.ui.week||0, mon = -3 + wk*7, wkEv = all.filter(x=>x.d>=mon && x.d<=mon+6);
  const days = [0,1,2,3,4,5,6].filter(i => i<5 || wkEv.some(x=>x.d===mon+i));
  const pick = all.find(x=>x.id===S.ui.selSea) || wkEv.filter(x=>x.d>=0).sort((a,b)=>a.d-b.d||a.h-b.h)[0] || uNextSeances(fs)[0] || wkEv[0];
  const ev = x => { const past = x.done, cls = past ? 'past' : x.mode==='Virtuel' ? 'v' : 'p';
    return `<button class="uc-ev ${cls} ${pick&&pick.id===x.id?'sel':''}" data-act="u-sel" data-id="${x.id}"><span class="uc-h">${uH(hrs(x)).replace(/ h 00/g,' h')}</span><b>${esc(x.t)}</b><span class="uc-s">${past?(x.st==='absent'?'Absente':x.st==='retard'?'Retard':'Présente'):x.mode==='Virtuel'?'Visio':'Présentiel'} · ${x.f}</span></button>`; };
  const hrsTo = pick ? uHoursTo(pick) : 0;
  const detail = pick ? `<div class="panel panel-b"><div class="mb-2">${pick.done?pill('Terminée','grey'):pick.mode==='Virtuel'?pill(`Visio · ${hrsTo<24?`dans ${Math.max(1,hrsTo)} h`:relDay(pick.d).toLowerCase()}`,'info'):pill(`Présentiel · ${relDay(pick.d).toLowerCase()}`,'acc')}</div><h3 class="h2 mb-2" style="font-size:22px">${esc(pick.t)}</h3><div class="muted" style="font-size:15px;line-height:1.7">${fmtD(dateOf(pick),{weekday:'long',day:'numeric',month:'long'})} · ${uH(hrs(pick))}<br>Séance ${pick.n} · ${esc(fname(pick.f))}<br>Formateur : ${uTrainerOf(pick.f)}</div>
    ${!pick.done?`<p class="mt-3 mb-0">À préparer : relire le support de la séance précédente et apporter vos fichiers de travail.</p>`:''}
    <div class="d-flex flex-column gap-2 mt-3">${pick.done ? (pick.replay?`<button class="btn btn-primary w-100" data-act="u-seance" data-id="${pick.id}"><i class="fa-solid fa-play"></i>Voir le replay</button>`:`<button class="btn btn-primary w-100" data-act="u-seance" data-id="${pick.id}">Voir la séance</button>`) : pick.mode==='Virtuel' ? `<button class="btn btn-primary w-100" data-act="seance" data-id="${pick.id}"><i class="fa-solid fa-video"></i>Rejoindre la séance</button>` : `<button class="btn btn-primary w-100" data-act="seance" data-id="${pick.id}"><i class="fa-solid fa-location-dot"></i>Voir le lieu</button>`}<button class="btn btn-ghost w-100" data-act="u-agenda">Ajouter à mon agenda</button></div></div>` : '';
  const pres = uPres(fs), past = all.filter(x=>x.st), pr = past.filter(x=>x.st==='present').length, rt = past.filter(x=>x.st==='retard').length, ab = past.filter(x=>x.st==='absent').length;
  return `<div class="d-flex align-items-center gap-2 flex-wrap mb-4"><button class="btn btn-quiet btn-icon" data-act="week" data-w="-1" aria-label="Semaine précédente"><i class="fa-solid fa-chevron-left"></i></button><h2 class="h2 mb-0 px-1">Semaine du ${addDays(mon).getDate()} au ${fmtD(addDays(mon+6),{day:'numeric',month:'long',year:'numeric'})}</h2><button class="btn btn-quiet btn-icon" data-act="week" data-w="1" aria-label="Semaine suivante"><i class="fa-solid fa-chevron-right"></i></button>${wk?`<button class="btn btn-ghost btn-sm" data-act="week" data-w="0">Cette semaine</button>`:''}<div class="ms-auto">${segs}</div></div>
  <div class="u-grid u-2-1"><div class="panel u-cal-wrap"><div class="u-cal" style="--cols:${days.length}">${days.map(i=>{ const d = addDays(mon+i); return `<div class="uc-day ${mon+i===0?'today':''}"><div class="uc-dh"><span>${d.toLocaleDateString('fr-FR',{weekday:'long'})}</span><b>${d.getDate()}</b></div><div class="uc-db">${wkEv.filter(x=>x.d===mon+i).sort((a,b)=>a.h-b.h).map(ev).join('')}</div></div>`; }).join('')}</div></div>
  <div class="stack">${detail}${uCard('Mon assiduité', `<div class="d-flex align-items-baseline gap-2 flex-wrap"><span class="num-key">${pres} %</span><span class="small fw-sb ${pres>=80?'tx-ok':'tx-bad'}">Minimum requis : 80 %</span></div><div class="my-3">${uBar(pres, pres>=80?'ok':'bad')}</div><div class="d-flex gap-3 small muted"><span><b class="text-body">${pr}</b> présences</span><span><b class="text-body">${rt}</b> retard${rt>1?'s':''}</span><span><b class="text-body">${ab}</b> absence${ab>1?'s':''}</span></div><button class="link-u mt-3" data-act="u-sview" data-k="pres">Justifier une absence</button>`)}</div></div>`;
});
VIEWS['e-seances'].crumbTail = 'Planning';
ACT.week = el => { const w = +el.dataset.w; S.ui.week = w===0 ? 0 : Math.max(-2, Math.min(8,(S.ui.week||0)+w)); S.ui.selSea = null; rerender(); };
ACT['u-sel'] = el => { S.ui.selSea = el.dataset.id; if ((S.ui.sview||'semaine')!=='semaine') { const x = S.st.seances.find(s=>s.id===el.dataset.id); S.ui.sview = 'semaine'; S.ui.week = Math.floor((x.d+3)/7); } rerender(); };

/* ----- Travaux pratiques : liste à gauche, consigne et dépôt à droite ----- */
const U_TGRP = {open:t=>['afaire','encours','reprendre'].includes(t.status), sent:t=>t.status==='soumis', done:t=>t.status==='valide'};
const uTGroupOf = t => Object.keys(U_TGRP).find(k=>U_TGRP[k](t));
const U_CRIT = {DG:[["Hiérarchie de l'information",6],['Typographie',5],['Composition et grille',5],['Créativité',4]], CM:[['Pertinence stratégique',6],['Qualité des contenus',6],['Ligne éditoriale',4],['Présentation',4]], GIA:[['Exactitude des données',8],['Mise en forme',5],['Fonctions utilisées',4],['Présentation',3]]};
view('e-todo','etu','Travaux pratiques','fa-file-lines', () => {
  const fs = vf(), all = S.st.todos.filter(t=>fs.includes(t.f)), g = S.ui.tgrp || 'open';
  const list = all.filter(U_TGRP[g]).sort((a,b)=>g==='open'?a.due-b.due:b.due-a.due);
  const t = list.find(x=>x.id===S.ui.tsel) || list[0];
  const lab = {open:'À rendre', sent:'Rendus', done:'Corrigés'};
  const left = `${uSeg(Object.keys(lab).map(k=>[k, `${lab[k]} (${all.filter(U_TGRP[k]).length})`]), g, 'u-tgrp', {soft:true, cls:'block mb-3'})}
    ${list.length ? list.map(x=>`<div class="box-row d-block clickable ${t&&x.id===t.id?'sel':''}" data-act="u-tsel" data-id="${x.id}" role="button" tabindex="0"><div class="d-flex justify-content-between gap-2 align-items-start"><b class="fw-sb" style="font-size:15px">${esc(x.t)}</b>${g==='open'?(x.status==='reprendre'?pill('À reprendre','bad'):pill(dueTxt(x.due),dueTone(x.due))):g==='sent'?pill('En validation','mute'):pill(`Corrigé${x.grade?' · '+x.grade+'/20':''}`,'ok')}</div><div class="small muted mt-1">${x.f} · ${g==='open'?'à rendre le '+fmtDM(addDays(x.due)):'rendu le '+fmtDM(addDays(Math.min(0,x.due)))}</div></div>`).join('') : uEmpty(g==='open'?'Aucun travail à rendre':'Rien ici pour le moment', g==='open'?'Vous êtes à jour. Les nouveaux travaux apparaîtront ici.':'', `<a class="btn btn-ghost btn-sm" href="#e-seances">Voir mes séances</a>`)}`;
  if (!t) return `<div class="u-grid u-l-r"><div>${left}</div><div></div></div>`;
  const k = wStage(t.status), lastAdm = [...t.hist].reverse().find(h=>h.w!=='Vous');
  const due = t.status==='valide'||t.status==='soumis' ? '' : `<span class="pill ${t.due<0?'p-bad':'p-warn'} nodot" style="font-size:14px;padding:.4rem .8rem">${t.due<0?'En retard · à rendre au plus vite':`À rendre avant le ${uDueDate(t.due)}, 23 h 59`}</span>`;
  const files = t.files.map((f,i)=>`<div class="file-row"><span class="ftype">${frFile(f)}</span><div class="lr-m"><div class="fw-sb small">${esc(f)}</div>${uBar(100,'ok thin')}</div><span class="small muted">${(2+i*3.2).toFixed(1).replace('.',',')} Mo</span>${k===1?`<button class="btn btn-quiet btn-sm btn-icon border-0 bg-transparent tx-bad" data-act="u-file-del" data-id="${t.id}" data-i="${i}" aria-label="Retirer ${esc(f)}"><i class="fa-solid fa-trash-can"></i></button>`:''}</div>`).join('');
  let stage = '';
  if (k===0) stage = `<div class="alert-strip as-info mt-4"><i class="fa-solid fa-circle-info"></i><span><b class="at">Lisez la consigne, puis démarrez</b>L'administration et votre formateur seront informés que vous avez commencé.</span></div><div class="d-flex justify-content-end mt-4"><button class="btn btn-primary" data-act="todo-start" data-id="${t.id}"><i class="fa-solid fa-play"></i>Je démarre</button></div>`;
  else if (k===1) stage = `${t.status==='reprendre'?`<div class="alert-strip as-bad mt-4"><i class="fa-solid fa-triangle-exclamation"></i><span><b class="at">À reprendre</b>${esc(lastAdm?.c||'Votre dépôt doit être repris.')}</span></div>`:''}
    <div class="wa-card mt-4"><i class="fa-brands fa-whatsapp"></i><div class="lr-m"><b>Corrections dans ${esc(CLASSE[t.f])}</b><div class="small muted">Publiez vos versions dans le groupe : vos formateurs vous y répondent.</div></div><button class="btn btn-ghost btn-sm" data-act="wa-open" data-f="${t.f}">Ouvrir le groupe</button></div>
    <h3 class="h3 mt-4 mb-2">Mon dépôt</h3>
    <form id="td-form" data-submit="todo-submit" data-id="${t.id}" novalidate class="d-flex flex-column gap-3">
      <label class="dropzone text-center mb-0" for="td-files"><i class="fa-solid fa-upload"></i><span class="dz-t">Glissez vos fichiers ici ou <u>parcourez</u></span>PDF, JPG, PNG ou ZIP · 50 Mo maximum par fichier</label><input type="file" id="td-files" multiple hidden data-chg="u-td-files">
      <div id="td-picked">${files}</div>
      <input class="form-control" id="td-link" type="url" placeholder="Ou un lien (Drive, Behance, Canva…)" aria-label="Lien vers votre travail">
      <div><label class="form-label" for="td-msg">Message au formateur (facultatif)</label><textarea class="form-control" id="td-msg" rows="3" placeholder="Précisez vos choix, vos difficultés…"></textarea></div>
      <label class="d-flex gap-2 small align-items-start"><input class="form-check-input mt-0" type="checkbox" required id="td-ok">Mon travail a été corrigé et validé dans la classe virtuelle</label>
      <div class="d-flex justify-content-end gap-2 flex-wrap"><button type="button" class="btn btn-ghost" data-act="u-draft">Enregistrer le brouillon</button><button class="btn btn-primary" type="submit">Déposer mon travail</button></div>
    </form>`;
  else if (k===3) stage = `<div class="alert-strip as-warn mt-4"><i class="fa-solid fa-clock"></i><span><b class="at">Travail déposé</b>L'administration va le valider définitivement. Vous serez notifiée.</span></div><h3 class="h3 mt-4 mb-2">Mon dépôt</h3>${files}`;
  else stage = `<div class="alert-strip as-ok mt-4"><i class="fa-solid fa-circle-check"></i><span><b class="at">Travail validé${t.grade?` · ${uApp(t.grade)[0]}`:''}</b>${esc(lastAdm?.c||'Bravo, votre travail est validé définitivement.')}</span></div><h3 class="h3 mt-4 mb-2">Mon dépôt</h3>${files}`;
  return `<div class="u-grid u-l-r"><div>${left}</div>
  <section class="panel card-pad"><div class="d-flex justify-content-between gap-3 flex-wrap align-items-start"><div style="min-width:0"><div class="small muted">${esc(fname(t.f))} · ${esc(t.type)} · ${uTrainerOf(t.f)}</div><h2 class="h2 mb-0" style="font-size:26px;line-height:34px">${esc(t.t)}</h2></div>${due}</div>
    <div class="mt-4">${wSteps(t.status)}</div>
    <h3 class="h3 mb-2">Consigne</h3><p class="mb-0" style="white-space:pre-line">${esc(t.brief)}</p>
    <h3 class="h3 mt-4 mb-2">Critères d'évaluation</h3><div class="crit-grid">${U_CRIT[t.f].map(c=>`<div class="lrow m-0"><span class="lr-m" style="font-size:14px">${c[0]}</span><b class="small">${c[1]} pts</b></div>`).join('')}</div>
    ${stage}
    ${t.hist.length?`<h3 class="h3 mt-4 mb-2">Historique</h3><ul class="timeline mb-0">${t.hist.map(h=>`<li class="${h.w==='Vous'?'cur':'ok'}"><span class="tdot"></span><b class="small">${esc(h.w)}</b> <span class="small muted">· ${relDay(h.d).toLowerCase()}</span><div class="small">${esc(h.c)}</div></li>`).join('')}</ul>`:''}
  </section></div>`;
});
