/* ----- Évaluations et notes ----- */
view('e-evaluations','etu','Évaluations','fa-chart-column', () => {
  const fs = vf(), ev = S.st.evals.filter(e=>fs.includes(e.f)), noted = ev.filter(e=>e.note!=null), ok = noted.filter(e=>e.note>=10).length;
  const nxt = ev.filter(e=>e.note==null && !e.pending).sort((a,b)=>a.d-b.d)[0];
  const comment = S.st.todos.filter(t=>fs.includes(t.f)).flatMap(t=>t.hist.filter(h=>h.w!=='Vous' && h.w!=='Administration').map(h=>({...h, t:t.t}))).sort((a,b)=>b.d-a.d)[0];
  const res = e => e.note!=null ? (e.note>=10?pill('Validé','ok'):pill('À reprendre','bad')) : e.open ? `<button class="link-u" data-act="u-quiz" data-id="${e.id}">Passer</button>` : pill(e.pending?'En cours de correction':'À venir', e.pending?'warn':'grey');
  return `<div class="u-grid u-3">
    ${uKpi('Évaluations validées', `${ok}<small> sur ${ev.length}</small>`, 'Validation sur critères professionnels', '', '', '', 'dark')}
    ${uKpi('Compétences acquises', `${noted.length?Math.round(ok/noted.length*100):0} %`, `${noted.length} évaluation${noted.length>1?'s':''} corrigée${noted.length>1?'s':''}`, '')}
    <div class="ukpi"><div class="uk-h">Prochaine évaluation</div>${nxt?`<div class="h3 mt-2 mb-1" style="font-size:22px">${esc(nxt.t)}</div><div class="small muted">${uDueDate(nxt.d)} · ${nxt.type==='QCM'?'20 min · en ligne':'en présentiel'}</div>${nxt.open?`<button class="btn btn-primary btn-sm mt-3 align-self-start" data-act="u-quiz" data-id="${nxt.id}">Commencer le quiz</button>`:''}`:'<div class="small muted mt-2">Aucune évaluation programmée.</div>'}</div>
  </div>
  <div class="u-grid u-2-1 mt-4"><section class="panel"><div class="panel-h"><h2>Suivi des évaluations</h2><span class="sub ms-auto">Mis à jour le ${fmtDM(TODAY)}</span></div><div class="tbl mt-3"><table class="table"><thead><tr>${fs.length>1?'<th>Formation</th>':''}<th>Évaluation</th><th>Type</th><th>Appréciation</th><th>Résultat</th></tr></thead><tbody>${ev.sort((a,b)=>a.d-b.d).map(e=>`<tr>${fs.length>1?`<td>${fchip(e.f)}</td>`:''}<td class="tdn">${esc(e.t.split(' — ')[1]||e.t)}</td><td>${esc(e.type)}</td><td>${e.note!=null?uAppPill(e.note):'<span class="muted">—</span>'}</td><td>${res(e)}</td></tr>`).join('')}</tbody></table></div></section>
  <div class="stack">${uCard('Compétences par formation', fs.map(f=>{ const E = S.st.evals.filter(e=>e.f===f), V = E.filter(e=>e.note!=null && e.note>=10).length; return `<div class="mb-3"><div class="d-flex justify-content-between small fw-sb mb-1"><span>${fchip(f)} <span class="ms-1">${esc(uFShort(f))}</span></span><b>${V} / ${E.length} validées</b></div>${uBar(E.length?V/E.length*100:0, V===E.length?'ok':'')}</div>`; }).join('') + `<p class="small muted mb-0">Chaque évaluation est validée sur des critères professionnels. Aucune note chiffrée n'est attribuée.</p>`)}
  ${comment?uCard('Dernière appréciation', `<p class="mb-3" style="font-size:15px">« ${esc(comment.c)} »</p><div class="d-flex align-items-center gap-2">${uIni(comment.w,'sm')}<div><div class="fw-sb small">${esc(comment.w)}</div><div class="small muted">${esc(comment.t)}</div></div></div>`):''}</div></div>`;
});
Object.assign(VIEWS['e-evaluations'], {title:'Évaluations', crumbTail:'Évaluations', cta:`<button class="btn btn-primary t-cta" data-act="fake-dl" data-n="Attestation de compétences provisoire.pdf"><i class="fa-solid fa-download"></i>Mon attestation de compétences</button>`});
ACT['u-quiz'] = el => { S.qz = null; uGo('e-quiz', {quizId: el.dataset.id}); };

/* ----- Quiz chronométré ----- */
const U_QX = [
  {q:"Quel élément garantit la lisibilité d'un logo en très petite taille, par exemple en favicon ?",o:['Un dégradé riche en couleurs','Un symbole simple aux formes pleines','Un slogan placé sous le logo','Une typographie fine et détaillée'],a:1},
  {q:'Quelle résolution utiliser pour une affiche imprimée ?',o:['72 ppp','150 ppp','300 ppp','1 200 ppp'],a:2},
  {q:"Dans Illustrator, quel outil permet de tracer des courbes de Bézier ?",o:['La plume','Le pinceau','La gomme','La pipette'],a:0},
  {q:"Qu'est-ce qu'un BAT ?",o:['Un format de fichier','Un bon à tirer validé avant impression','Une police de caractères','Un réglage de couleur'],a:1},
  {q:"Combien de polices de caractères est-il conseillé d'utiliser au maximum sur une affiche ?",o:['Une seule','Deux ou trois','Cinq','Autant que nécessaire'],a:1},
  {q:"Quel format exporter pour un logo à fond transparent destiné au web ?",o:['JPG','PNG ou SVG','BMP','TIFF non compressé'],a:1}];
view('e-quiz','etu','Quiz','fa-chart-column', () => {
  const e = S.st.evals.find(x=>x.id===S.ui.quizId) || (S.qz && S.st.evals.find(x=>x.id===S.qz.id)) || S.st.evals.find(x=>x.open) || S.st.evals[0];
  const Q = [...S.st.qcm.map(x=>({...x})), ...U_QX].slice(0,10);
  S.qz = S.qz && S.qz.id===e.id ? S.qz : {id:e.id, i:0, ans:{}, mark:{}, end:Date.now()+20*60000, done:false};
  const z = S.qz;
  if (z.done) { const good = Q.filter((q,i)=>z.ans[i]===q.a).length, note = Math.round(good/Q.length*40)/2;
    return `<div class="u-grid u-2-1"><div class="stack"><section class="panel card-pad text-center"><div class="ok-circle mx-auto mb-3"><i class="fa-solid fa-check"></i></div><h2 class="h2">Quiz terminé</h2><div class="my-3">${note>=10?pill('Compétence validée','ok'):pill('À reprendre','bad')}</div><p class="muted mb-4">${good} bonne${good>1?'s':''} réponse${good>1?'s':''} sur ${Q.length} · ${note>=10?'résultat enregistré dans votre suivi':'votre formateur vous proposera une reprise'}</p><div class="d-flex gap-2 justify-content-center flex-wrap"><a class="btn btn-primary" href="#e-evaluations">Voir mes évaluations</a><a class="btn btn-ghost" href="#e-dashboard">Tableau de bord</a></div></section>
      ${uCard('Correction', Q.map((q,i)=>`<div class="box-row d-block"><div class="fw-sb small mb-1">${i+1}. ${esc(q.q)}</div><div class="small ${z.ans[i]===q.a?'tx-ok':'tx-bad'}"><i class="fa-solid ${z.ans[i]===q.a?'fa-circle-check':'fa-circle-xmark'} me-1"></i>${z.ans[i]!=null?esc(q.o[z.ans[i]]):'Sans réponse'}${z.ans[i]!==q.a?` · bonne réponse : <b>${esc(q.o[q.a])}</b>`:''}</div></div>`).join(''))}</div><div></div></div>`; }
  const q = Q[z.i], answered = Object.keys(z.ans).length;
  return `<div class="u-grid u-2-1"><div><div class="d-flex align-items-center gap-3 mb-4"><div class="flex-grow-1">${uBar((z.i+1)/Q.length*100,'cor')}</div><b class="small nowrap">Question ${z.i+1} / ${Q.length}</b></div>
    <section class="panel card-pad"><div class="small-caps tx-c mb-2">Question ${z.i+1} sur ${Q.length}</div><h2 class="h2 mb-4" style="font-size:24px;line-height:32px">${esc(q.q)}</h2>
    ${q.o.map((o,j)=>`<label class="opt ${z.ans[z.i]===j?'on':''}"><input class="form-check-input" type="radio" name="qz" value="${j}" ${z.ans[z.i]===j?'checked':''} data-chg="u-qz-ans"><span class="opt-l">${'ABCD'[j]}</span><span>${esc(o)}</span></label>`).join('')}
    <label class="d-flex gap-2 align-items-center small mt-3 muted"><input class="form-check-input mt-0" type="checkbox" ${z.mark[z.i]?'checked':''} data-chg="u-qz-mark">Marquer pour revoir avant de terminer</label></section>
    <div class="d-flex justify-content-between mt-4"><button class="btn btn-ghost" data-act="u-qz-go" data-d="-1" ${z.i===0?'disabled':''}>‹ Question précédente</button>${z.i<Q.length-1?`<button class="btn btn-indigo" data-act="u-qz-go" data-d="1">Question suivante ›</button>`:`<button class="btn btn-primary" data-act="u-qz-end">Terminer le quiz</button>`}</div></div>
  <div class="stack"><div class="dark-card d-flex align-items-center gap-3"><i class="fa-solid fa-stopwatch" style="font-size:28px;color:var(--c300)"></i><div><div class="small" style="color:#C9C6E8">Temps restant</div><div class="num-key" id="qz-time" style="color:#fff">20:00</div></div></div>
    ${uCard('Navigation', `<div class="qz-grid">${Q.map((_,i)=>`<button class="${i===z.i?'cur':''} ${z.mark[i]?'mk':z.ans[i]!=null?'an':''}" data-act="u-qz-to" data-i="${i}" aria-label="Question ${i+1}">${i+1}</button>`).join('')}</div><div class="d-flex gap-3 small mt-3 flex-wrap"><span><i class="qlg qlg-an"></i>Répondue</span><span class="tx-warn"><i class="qlg qlg-mk"></i>À revoir</span><span class="muted"><i class="qlg"></i>Non répondue</span></div>`)}
    ${uCard('Règles', `<p class="small muted mb-0">${Q.length} questions · 20 minutes · une seule tentative. Vos réponses sont enregistrées automatiquement (<span id="qz-cnt">${answered}</span> / ${Q.length}).</p>`)}
    <button class="btn btn-corail-line w-100" data-act="u-qz-end">Terminer le quiz</button></div></div>`;
}, () => qzTick());
Object.assign(VIEWS['e-quiz'], {parent:'e-evaluations', title:() => { const e = S.st.evals.find(x=>x.id===(S.qz&&S.qz.id)) || S.st.evals.find(x=>x.id===S.ui.quizId) || S.st.evals.find(x=>x.open); return 'Quiz · ' + esc((e?e.t:'').replace(/^QCM — /,'')); }, crumb:'Espace étudiant <span class="sep">›</span> Évaluations <span class="sep">›</span> Quiz'});
let QZ_T = null;
function qzTick(){ clearInterval(QZ_T); const paint = () => { const el = $('#qz-time'); if (!el || S.view!=='e-quiz' || !S.qz || S.qz.done) { clearInterval(QZ_T); return; } const s = Math.max(0, Math.round((S.qz.end-Date.now())/1000)); el.textContent = `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`; if (!s) ACT['u-qz-finish'](); }; paint(); QZ_T = setInterval(paint, 1000); }
INP['u-qz-ans'] = el => { S.qz.ans[S.qz.i] = +el.value; $$('.opt').forEach((o,j)=>o.classList.toggle('on', j===+el.value)); const b = $(`.qz-grid button[data-i="${S.qz.i}"]`); if (b && !S.qz.mark[S.qz.i]) b.classList.add('an'); const c = $('#qz-cnt'); if (c) c.textContent = Object.keys(S.qz.ans).length; };
INP['u-qz-mark'] = el => { S.qz.mark[S.qz.i] = el.checked; rerender(); };
ACT['u-qz-go'] = el => { S.qz.i += +el.dataset.d; rerender(); };
ACT['u-qz-to'] = el => { S.qz.i = +el.dataset.i; rerender(); };
ACT['u-qz-end'] = () => { const n = 10 - Object.keys(S.qz.ans).length; openModal({title:'Terminer le quiz ?', body:`<p class="mb-0">${n?`Il vous reste <b>${n} question${n>1?'s':''} sans réponse</b>. `:''}Une fois terminé, vous ne pourrez plus modifier vos réponses.</p>`, foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Continuer</button><button class="btn btn-primary" data-act="u-qz-finish">Terminer</button>`}); };
ACT['u-qz-finish'] = () => { const z = S.qz, Q = [...S.st.qcm, ...U_QX].slice(0,10), good = Q.filter((q,i)=>z.ans[i]===q.a).length, note = Math.round(good/Q.length*40)/2, e = S.st.evals.find(x=>x.id===z.id);
  z.done = true; e.note = note; e.open = false; S.st.notifs.unshift({id:'n'+Date.now(),cat:'Évaluations',f:e.f,t:`Résultat publié : ${e.t} — ${note>=10?'compétence validée':'à reprendre'} (${good} bonnes réponses sur ${Q.length}).`,d:"À l'instant",read:false}); audit('Quiz terminé', `${e.t} — ${good}/${Q.length} bonnes réponses`); closeModal(); rerender(); toast(`Quiz terminé : ${good} bonnes réponses sur ${Q.length} — ${note>=10?'compétence validée':'à reprendre'}.`); };

