    S.st.notifs.unshift({id:'n'+Date.now(),cat:'Paiements',f:null,t:`Paiement de ${fcfa(amt)} reçu (${mode}). Reçu ${ref} disponible.`,d:"À l'instant",read:false}); audit('Paiement en ligne', `${ref} — ${fcfa(amt)} — ${mode}`);
