view('e-certification','etu','Certification','fa-award', () => {
  const fs = vf(); if (!fs.includes(S.ui.cf)) S.ui.cf = fs[0]; const f = S.ui.cf, c = certCriteria(f), ok = c.filter(x=>x.s==='ok').length, elig = ok===c.length, s = S.st.student;
  const next = f==='DG' ? ['Studio Creative et test final', `Test final prévu le ${fmtD(addDays(40),{day:'numeric',month:'long'})}. Le jury du Studio Creative se réunit à la clôture de l'édition ${S.st.studio.edition}.`] : [`Fin du RECO 60 · jour ${recoDay(f)} sur 60`, 'Votre projet professionnel de 60 jours se termine bientôt : pensez à préparer votre bilan et votre rapport de fin de formation.'];
  return `${fs.length>1?`<div class="mb-4">${uSeg(fs.map(x=>[x, `${x} · ${uFShort(x)}`]), f, 'u-cf', {soft:true})}</div>`:''}
  <div class="u-grid u-2-1"><div class="stack"><section class="panel card-pad"><div class="d-flex justify-content-between gap-3 flex-wrap align-items-start"><div><h2 class="h2 mb-0" style="font-size:24px">Conditions d'éligibilité</h2><div class="muted">Certificat · ${esc(fname(f))}</div></div><span class="pill ${elig?'p-ok':'p-warn'}" style="font-size:14px;padding:.4rem .8rem">${ok} condition${ok>1?'s':''} remplie${ok>1?'s':''} sur ${c.length}</span></div>
    <div class="my-4">${uBar(ok/c.length*100,'cor')}</div>
    ${c.map(x=>`<div class="box-row clickable" data-go="${x.link}" role="link" tabindex="0"><span class="crit-ic ${x.s}">${x.s==='ok'?'<i class="fa-solid fa-check"></i>':x.s==='ko'?'<i class="fa-solid fa-xmark"></i>':'•'}</span><div class="lr-m"><div class="fw-sb">${esc(x.t)}</div><div class="small muted">${esc(x.d)}</div></div>${pill(x.s==='ok'?'Rempli':x.s==='ko'?'À régulariser':'En cours', x.s==='ok'?'ok':x.s==='ko'?'bad':'warn')}</div>`).join('')}</section>
    ${uCard('Mes documents', `<div class="lrow"><i class="fa-solid fa-file-lines" style="font-size:20px"></i><div class="lr-m"><div class="lr-t">Attestation d'inscription</div><div class="lr-s">PDF · délivrée le ${s.since}</div></div><button class="link-u" data-act="fake-dl" data-n="Attestation d'inscription">Télécharger</button></div><div class="lrow"><i class="fa-solid fa-file-lines" style="font-size:20px"></i><div class="lr-m"><div class="lr-t">Attestation de présence</div><div class="lr-s">PDF · mise à jour chaque mois</div></div><button class="link-u" data-act="fake-dl" data-n="Attestation de présence">Télécharger</button></div><div class="lrow ${elig?'':'opacity-75'}"><i class="fa-solid ${elig?'fa-award':'fa-lock'}" style="font-size:20px"></i><div class="lr-m"><div class="lr-t">Certificat de réussite</div><div class="lr-s">${elig?'Disponible':'Disponible une fois toutes les conditions remplies'}</div></div>${elig?`<button class="link-u" data-act="u-cert" data-f="${f}">Voir</button>`:''}</div>`)}</div>
  <div class="stack">${uCard('Aperçu du certificat', `<div class="cert-mini ${elig?'clickable':''}" ${elig?`data-act="u-cert" data-f="${f}"`:''}><div class="cm-k">Certificat de réussite</div><div class="cm-n">${esc(s.first)} ${esc(s.last)}</div>${elig?'':`<span class="cm-lock"><i class="fa-solid fa-lock"></i>Disponible après validation</span>`}<div class="cm-sym">${logoSym('couleur')}</div></div>`)}
    <div class="dark-card"><div class="kc mb-2">Prochaine étape</div><h3 class="h3" style="font-size:21px">${next[0]}</h3><p class="mt-2">${next[1]}</p></div></div></div>`;
});
ACT['u-cert'] = el => { const s = S.st.student, f = el.dataset.f; openModal({title:'Mon certificat', size:'modal-lg', body:certDoc({name:`${s.first} ${s.last}`, formation:fname(f), session:s.session, mention:'Bien', code:certCode(s.matricule,f)}), foot:`<button class="btn btn-ghost" data-act="close-modal">Fermer</button><button class="btn btn-primary" data-act="fake-dl" data-n="Certificat ${f}.pdf">Télécharger (PDF)</button>`}); };

/* ----- Messagerie (deux colonnes) ----- */
function messagingView(threads){
  if (!threads.find(t=>t.id===S.ui.thread)) S.ui.thread = threads[0]?.id; const th = threads.find(t=>t.id===S.ui.thread), q = norm(S.ui.chatQ||'');
  const list = threads.filter(t=>!q || norm(t.who+' '+t.msgs.map(m=>m.t).join(' ')).includes(q));
  const time = m => (m.d||'').replace(/^(Lun|Mar|Mer|Jeu|Ven|Sam|Dim)\.? /,'').replace("À l'instant",'maintenant');
  const msg = m => { const f = (m.t.match(/\(pièce jointe : ([^)]+)\)/)||[])[1], txt = m.t.replace(/\s*\(pièce jointe : [^)]+\)/,''); return `${txt?`<div class="msg ${m.me?'me':''}">${esc(txt)}</div><small class="msg-t ${m.me?'me':''}">${esc(time(m))}</small>`:''}${f?`<div class="msg-file ${m.me?'me':''}"><span class="ftype">${frFile(f)}</span><div><b class="small">${esc(f)}</b><div class="small muted">2,4 Mo</div></div></div>`:''}`; };
  return `<section class="panel u-chat"><div class="uc-list"><div class="p-3"><label class="search-field mb-0"><i class="fa-solid fa-magnifying-glass"></i><input class="form-control form-control-sm" placeholder="Rechercher une conversation" data-inp="u-chat-q" value="${esc(S.ui.chatQ||'')}" aria-label="Rechercher une conversation"></label></div><div id="uc-threads">${list.map(t=>{ const last = t.msgs[t.msgs.length-1]; return `<button class="uc-th ${t.id===S.ui.thread?'on':''}" data-act="thread" data-id="${t.id}">${uIni(t.who,'sm')}<span class="lr-m"><span class="d-flex justify-content-between gap-2"><b>${esc(t.who)}</b><small class="muted">${esc(time(last).split(' ').pop())}</small></span><span class="uc-last">${esc(last.t)}</span></span>${t.unread?`<span class="count">${t.unread}</span>`:''}</button>`; }).join('') || '<p class="small muted px-3">Aucune conversation.</p>'}</div></div>
  <div class="uc-main">${th?`<div class="uc-head">${uIni(th.who,'sm')}<div><b>${esc(th.who)}</b><div class="small ${/Format/.test(th.role)?'tx-ok':'muted'} fw-sb">${esc(th.role)}${/Format/.test(th.role)?' · en ligne':''}</div></div></div><div class="thread" id="thread"><span class="day-chip">Cette semaine</span>${th.msgs.map(msg).join('')}</div>
    <form data-submit="msg-send" class="uc-compose"><label class="btn btn-soft btn-icon mb-0" for="msg-file" title="Joindre un fichier" aria-label="Joindre un fichier"><i class="fa-solid fa-plus"></i></label><input type="file" id="msg-file" hidden><input class="form-control" id="msg-in" placeholder="Écrire un message..." required aria-label="Message"><button class="btn btn-primary btn-icon rounded-circle" type="submit" aria-label="Envoyer"><i class="fa-solid fa-paper-plane"></i></button></form>`:uEmpty('Aucune conversation','Écrivez à votre formateur ou à la scolarité.',`<button class="btn btn-ghost btn-sm" data-act="msg-new">Nouveau message</button>`)}</div></section>`;
}
INP['u-chat-q'] = el => { S.ui.chatQ = el.value; const keep = el.selectionStart; rerender(); const i = $('[data-inp="u-chat-q"]'); if (i) { i.focus(); i.setSelectionRange(keep, keep); } };
VIEWS['e-messagerie'].crumbTail = 'Messages'; VIEWS['e-messagerie'].cta = `<button class="btn btn-primary t-cta" data-act="msg-new"><i class="fa-solid fa-plus"></i>Nouveau message</button>`;
if (VIEWS['t-messagerie']) VIEWS['t-messagerie'].cta = VIEWS['e-messagerie'].cta;

