view('e-insertion','etu','Insertion pro','fa-briefcase', () => {
  S.st.apps = S.st.apps || [{t:'Infographiste print',co:'Imprimerie Nouvelle',d:'12 octobre',st:'Entretien'},{t:'Chargé(e) de contenus',co:"Orange Côte d'Ivoire",d:'8 octobre',st:'En attente'},{t:'Mission logo',co:'Maquis Chez Tantie Rose',d:'3 octobre',st:'Consultée'}];
  const flt = S.ui.ofilt || 'all', offers = S.offers.filter(o=>o.st==='Ouverte' && (flt==='all' || o.type===({stage:'Stage',emploi:'Emploi',mission:'Mission'})[flt]));
  const extra = [{t:"Création d'une identité visuelle",co:"Entreprise d'import-export",type:'Mission',f:'DG',d:'3 semaines',st:'Ouverte'}].filter(o=>flt==='all'||flt==='mission');
  const pc = Math.min(100, 40 + S.st.pressbook.length*6 + (S.st.cv.visible?10:0)), applied = t => S.st.apps.some(a=>a.t===t);
  return `<section class="hero2">${motif('h2-motif')}${star('h2-star')}<div class="d-flex justify-content-between gap-4 flex-wrap align-items-center"><div style="flex:1 1 420px"><div class="h2-kc">Mon profil professionnel</div><h2>Complété à ${pc} %</h2><div style="max-width:440px" class="my-3">${uBar(pc)}</div><p>Ajoutez deux réalisations à votre pressbook pour être visible des recruteurs partenaires.</p></div><div class="d-flex gap-2 flex-wrap"><a class="btn btn-primary" href="#e-projets">Compléter mon portfolio</a><a class="btn btn-white-line" href="#e-cv">Mettre à jour mon CV</a></div></div></section>
  <div class="u-grid u-2-1 mt-4"><div><div class="d-flex align-items-center gap-3 flex-wrap mb-3"><h2 class="h2 mb-0">Offres pour vous</h2><div class="chips ms-auto">${[['all','Toutes'],['stage','Stages'],['emploi','Emplois'],['mission','Missions']].map(([k,l])=>`<button class="chip-filter ${flt===k?'on':''}" data-act="u-ofilt" data-k="${k}">${l}</button>`).join('')}</div></div>
    ${[...offers, ...extra].map(o=>{ const m = uOfferMeta(o); return `<div class="box-row offer"><span class="ini sq ini-${hueOf(o.co)%5}" style="width:52px;height:52px;font-size:16px">${esc(initials(o.co))}</span><div class="lr-m"><div class="fw-sb" style="font-size:17px">${esc(o.t)}</div><div class="small muted">${esc(o.co)} · ${m.city}</div><div class="d-flex gap-2 flex-wrap mt-2">${pill(`${o.type} · ${o.d}`,'mute')}${pill(m.mode,'grey')}${pill(`Correspond à ${m.match} %`,'ok')}</div></div>${applied(o.t)?pill('Candidature envoyée','info'):`<button class="btn btn-ghost" data-act="u-apply" data-t="${esc(o.t)}" data-co="${esc(o.co)}">Postuler</button>`}</div>`; }).join('') || uEmpty('Aucune offre dans cette catégorie','Revenez bientôt : la cellule insertion publie de nouvelles offres chaque semaine.')}</div>
  <div class="stack">${uCard('Mes candidatures', S.st.apps.map(a=>`<div class="d-flex justify-content-between align-items-center gap-2 py-2 border-bottom-soft"><div><div class="fw-sb small">${esc(a.t)}</div><div class="small muted">Envoyée le ${esc(a.d)}</div></div>${pill(a.st, a.st==='Entretien'?'ok':a.st==='En attente'?'warn':a.st==='Envoyée'?'info':'info')}</div>`).join(''))}
    ${uCard('Événements carrière', [[21,'Job dating des créatifs','En ligne · 15 h'],[29,'Atelier : réussir son portfolio','Atelier EVC · 10 h']].map(([d,t,s])=>`<div class="d-flex align-items-center gap-3 py-2 clickable" data-act="u-event" data-t="${t}">${uDbox(addDays(d), d>25?'lav':'cor')}<div><div class="fw-sb small">${t}</div><div class="small muted">${s}</div></div></div>`).join(''))}</div></div>`;
});
VIEWS['e-insertion'].crumbTail = 'Carrière';
ACT['u-apply'] = el => { const s = S.st.student; openModal({title:`Ma candidature · ${esc(el.dataset.t)}`, size:'modal-lg', body:`<p class="muted">${esc(el.dataset.co)}</p><div class="form-label">Documents joints</div>${[['PDF',`CV · ${s.first} ${s.last}`,'Mis à jour le 20 octobre',1],['LIEN','Portfolio MY EVC',`${S.st.pressbook.length} projets publiés`,1],['PDF','Attestation de formation','Disponible dans Mes documents',0]].map(([b,t,d,c],i)=>`<label class="pm-opt ${c?'on':''} mb-2"><input class="form-check-input mt-0" type="checkbox" ${c?'checked':''}><span class="ftype">${b}</span><span><b class="small d-block">${t}</b><span class="small muted">${d}</span></span></label>`).join('')}
    <label class="form-label mt-3" for="ap-m">Message de motivation</label><textarea class="form-control" id="ap-m" rows="5" maxlength="1000" data-inp="u-ap-count">Madame, Monsieur, je termine ma formation à l'École Virtuelle des Créatifs, où j'ai réalisé plusieurs projets complets. Votre structure m'attire pour…</textarea><div class="small muted text-end mt-1" id="ap-c"></div>`,
    foot:`<button class="btn btn-ghost" data-act="close-modal">Enregistrer le brouillon</button><button class="btn btn-primary" data-act="u-apply-send" data-t="${esc(el.dataset.t)}">Envoyer ma candidature</button>`, onShow:()=>INP['u-ap-count']($('#ap-m'))}); };
INP['u-ap-count'] = el => { const c = $('#ap-c'); if (c) c.textContent = `${el.value.length} / 1 000 caractères`; };
ACT['u-apply-send'] = el => { S.st.apps.unshift({t:el.dataset.t, co:'', d:fmtDM(TODAY), st:'Envoyée'}); closeModal(); rerender(); toast('Candidature envoyée. La cellule insertion suit votre dossier.'); };
ACT['u-event'] = el => toast(`Inscription confirmée : ${esc(el.dataset.t)}.`);

/* ----- Mon profil (onglets) ----- */
view('e-profil','etu','Mon profil','fa-user', () => {
  const s = S.st.student, fs = fl(), tab = S.ui.ptab || 'info', avg = uAvg(fs);
  s.emergency = s.emergency || 'Jean Kouassi · 07 07 12 34 56';
  const head = `<section class="panel p-head"><div class="ph-av">${S.st.photo?`<span class="ini lg" style="background:var(--c300)"><img src="${S.st.photo}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%"></span>`:`<span class="ini lg" style="background:var(--c300)">${esc(initials(s.first+' '+s.last))}</span>`}<label class="ph-edit" for="ph-in" title="Modifier la photo"><i class="fa-solid fa-pen"></i></label><input type="file" id="ph-in" accept="image/*" hidden data-chg="photo"></div>
    <div class="ph-b"><h2 class="h2 mb-1" style="font-size:26px">${esc(s.first)} ${esc(s.last)}</h2><div class="muted">Matricule ${s.matricule} · ${fs.map(uFShort).join(' · ')} · ${esc(s.session.replace(' — Abidjan',''))}</div><div class="d-flex gap-2 mt-2 flex-wrap">${pill('Dossier complet','ok')}${pill('Membre depuis octobre 2026','mute')}</div></div>
    <div class="ph-stats"><div><small>Progression</small><b>${Math.round(fs.reduce((a,f)=>a+prog(f),0)/fs.length)} %</b></div><div><small>Assiduité</small><b>${uPres(fs)} %</b></div><div><small>Évaluations</small><b>${S.st.evals.filter(e=>fs.includes(e.f)&&e.note>=10).length} validées</b></div></div></section>`;
  const mobile = `<div class="d-lg-none mt-3 panel">${[['e-evaluations','fa-chart-column','Mes notes'],['e-certification','fa-award','Ma certification'],['e-messagerie','fa-message','Messages'],['e-insertion','fa-briefcase','Carrière et portfolio'],['e-notifications','fa-bell','Notifications'],['e-webtv','fa-tv','Web TV'],['e-assistance','fa-life-ring','Assistance']].map(([id,ic,l])=>`<a class="row-item clickable text-decoration-none" href="#${id}" style="color:var(--fg)"><i class="fa-solid ${ic}"></i><span class="ri-main fw-sb">${l}</span><i class="fa-solid fa-chevron-right muted"></i></a>`).join('')}</div>`;
  const tabs = uTabs([['info','Informations personnelles'],['parcours','Parcours'],['docs','Documents'],['pay','Paiements'],['notif','Notifications'],['secu','Sécurité']], tab, 'u-ptab');
  let body = '';
  if (tab==='info') { S.st.prefs = S.st.prefs || {note:1, rappel:1, echeance:1, offres:0};
    const fld = (id,l,v,o='') => `<div class="col-md-6"><label class="form-label" for="${id}">${l}</label><input class="form-control" id="${id}" value="${esc(v)}" ${o}></div>`;
    body = `<div class="u-grid u-2-1"><form class="panel card-pad" data-submit="u-prof-save" novalidate><div class="row g-3">${fld('pf-last','Nom',s.last,'required')}${fld('pf-first','Prénom',s.first,'required')}${fld('pc-mail','Adresse e-mail',s.email,'type="email" required')}${fld('pc-tel','Téléphone',s.phone,'required')}${fld('pf-birth','Date de naissance',s.birth.replace(/\//g,' / '),'readonly')}${fld('pc-city','Ville',s.city)}${fld('pf-urg',"Contact en cas d'urgence",s.emergency)}${fld('pf-port','Lien vers mon portfolio',s.links.behance?'https://'+s.links.behance:'')}</div><div class="d-flex justify-content-end gap-2 mt-4 pt-3 border-top-soft"><button type="button" class="btn btn-ghost" data-act="u-reset">Annuler</button><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>
    <div class="stack">${uCard('Pièces du dossier', ["Pièce d'identité","Photo d'identité",'Dernier diplôme','Justificatif de domicile'].map(x=>`<div class="d-flex justify-content-between align-items-center py-2 border-bottom-soft"><span>${x}</span>${pill('Validé','ok')}</div>`).join(''))}
    ${uCard('Je veux être prévenu·e', [['note','Nouvelle appréciation publiée'],['rappel','Rappel de séance (1 h avant)'],['echeance','Échéance de paiement'],['offres',"Offres d'emploi et de stage"]].map(([k,l])=>`<div class="d-flex justify-content-between align-items-center py-2"><span>${l}</span><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" role="switch" ${S.st.prefs[k]?'checked':''} data-chg="u-pref" data-k="${k}" aria-label="${l}"></div></div>`).join(''))}</div></div>`; }
  if (tab==='parcours') { const f0 = fs[0], cur = S.formations[f0].prog.find(y=>!y.done);
    const tl = [['done','1er octobre 2026','Préinscription',`Formation${fs.length>1?'s':''} choisie${fs.length>1?'s':''} : ${fs.map(uFShort).join(', ')} · frais de dossier réglés`],['done','3 octobre 2026','Dossier validé','4 pièces vérifiées par la scolarité'],['done',s.since,'Inscription et début de formation',`Matricule ${s.matricule} attribué`],['done','Octobre 2026',`Séances 1 à ${chaptersDone(f0)} · ${f0}`,`${chaptersDone(f0)} séances suivies · moyenne ${avgF(f0)??'—'} / 20`],['cur','En ce moment',`Séance ${cur?.n||'—'} · ${esc(cur?.t||'')}`,`${uOpenTodos(fs).length} travaux à rendre`],['todo','Novembre → décembre 2026',`Séances ${(cur?.n||0)+1} à ${chapters(f0)}`, S.formations[f0].prog.slice(-3).map(x=>x.t).join(', ')],['todo','Janvier 2027','Projet final et soutenance','Devant un jury de formateurs et de professionnels'],['todo','Mars 2027','Certification','Certificat de réussite MY EVC']];
    const acq = s.skills, nxt = ['Identité visuelle','Packaging','Portfolio','Campagnes publicitaires'];
    body = `<div class="u-grid u-2-1"><section class="panel card-pad"><h2 class="h3 mb-4" style="font-size:21px">Ma trajectoire à l'EVC</h2><ol class="u-tl">${tl.map(([st,d,t,x])=>`<li class="${st}"><span class="ut-dot">${st==='done'?'<i class="fa-solid fa-check"></i>':''}</span><div class="small ${st==='cur'?'tx-c fw-sb':'muted'}">${d}</div><div class="fw-sb" style="font-size:16px">${t}</div><div class="small muted">${x}</div></li>`).join('')}</ol></section>
    <div class="stack">${uCard('Compétences acquises', `<div class="d-flex gap-2 flex-wrap">${acq.map(k=>pill(k,'mute')).join('')}${nxt.map(k=>pill(k,'grey')).join('')}</div><p class="small muted mt-3 mb-0">En gris : compétences des séances à venir.</p>`)}
    ${uCard("Formations à l'EVC", fs.map(f=>`<div class="lrow"><div class="lr-m"><div class="lr-t">${esc(fname(f))}</div><div class="lr-s">Octobre 2026 → ${F[f].months>2?'février':'décembre'} 2027</div></div>${pill('En cours','ok')}</div>`).join('') + `<div class="dash-box mt-3"><div class="lr-m"><b class="small d-block">Suite conseillée</b><span class="small muted">Studio Creative · RECO 60 · insertion</span></div><a class="link-u small" href="#e-insertion">Découvrir</a></div>`)}</div></div>`; }
  if (tab==='docs') { S.st.mydocs = S.st.mydocs || [["Pièce d'identité",'PDF','Envoyée le 1er octobre 2026','Validé'],["Photo d'identité",'JPG','Envoyée le 1er octobre 2026','Validé'],['Dernier diplôme','PDF','Envoyé le 1er octobre 2026','Validé'],['Justificatif de domicile','PDF','Envoyé le 2 octobre 2026','Validé']];
    body = `<div class="u-grid u-1-1"><section class="panel"><div class="panel-h panel-sep"><div><h2>Pièces de mon dossier</h2><div class="sub">Envoyées lors de la préinscription</div></div></div>${S.st.mydocs.map(d=>`<div class="row-item"><span class="ftype">${d[1]}</span><div class="ri-main"><div class="ri-t">${esc(d[0])}</div><div class="ri-s">${d[2]}</div></div>${pill(d[3], d[3]==='Validé'?'ok':'warn')}<button class="link-u ms-2" data-act="fake-dl" data-n="${esc(d[0])}">${d[3]==='Validé'?'Voir':'Remplacer'}</button></div>`).join('')}<div class="p-3"><label class="dropzone d-flex align-items-center justify-content-center gap-2 py-3 mb-0" for="pd-in" style="flex-direction:row"><i class="fa-solid fa-upload" style="font-size:16px"></i><b class="m-0">Ajouter un document (justificatif d'absence, etc.)</b></label><input type="file" id="pd-in" hidden data-chg="u-doc-add"></div></section>
    <section class="panel"><div class="panel-h panel-sep"><div><h2>Documents délivrés par l'EVC</h2><div class="sub">Générés automatiquement, signés électroniquement</div></div></div>${[["Attestation d'inscription",`Délivrée le ${s.since}`,'fake-dl'],['Attestation de présence','Mise à jour le 1er de chaque mois','fake-dl'],['Relevé de notes provisoire',`Au ${fmtDM(TODAY)} 2026`,'fake-dl'],[`Reçus de paiement (${S.st.pay.tx.length})`,'Inscription et versements','go-pay'],['Carte étudiant numérique','Valable jusqu\'au 31 mars 2027','carte-etu']].map(([t,d,a])=>`<div class="row-item"><span class="nsq" style="width:40px;height:40px;flex-basis:40px;background:var(--i100);color:var(--i900)"><i class="fa-solid fa-file-lines"></i></span><div class="ri-main"><div class="ri-t">${t}</div><div class="ri-s">${d}</div></div><button class="btn btn-ghost btn-sm" data-act="${a}" data-n="${esc(t)}">${a==='carte-etu'?'Afficher':'Télécharger'}</button></div>`).join('')}<div class="row-item opacity-75"><span class="nsq" style="width:40px;height:40px;flex-basis:40px"><i class="fa-solid fa-lock"></i></span><div class="ri-main"><div class="ri-t">Certificat de réussite</div><div class="ri-s">Disponible après validation des conditions</div></div><span class="small fw-sb muted">Verrouillé</span></div></section></div>`; }
  if (tab==='pay') { const p = payState(); body = `<section class="panel card-pad"><div class="d-flex justify-content-between align-items-center gap-3 flex-wrap"><div><div class="small muted">Réglé</div><div class="num-key">${nfr(p.paid)} <small class="fw-sb muted" style="font-size:16px">/ ${fcfa(p.total)}</small></div></div><a class="btn btn-primary" href="#e-paiements">Ouvrir mes paiements</a></div><div class="mt-3">${uBar(p.paid/p.total*100,'ok lg')}</div></section>`; }
  if (tab==='notif') { const P = S.st.nprefs = S.st.nprefs || {};
    const rows = [['Séances',[['r1','Rappel 1 heure avant une séance',[1,0,1]],['r2','Séance déplacée ou annulée',[1,1,1]]]],['Travaux et évaluations',[['t1','Nouveau travail à rendre',[1,1,0]],['t2',"Rappel 48 h avant l'échéance",[1,0,1]],['t3','Appréciation publiée',[1,1,0]]]],['Paiements',[['p1','Rappel 7 jours avant une échéance',[1,1,1]],['p2','Paiement confirmé',[1,1,0]]]],['Échanges et carrière',[['m1',"Nouveau message d'un formateur",[1,0,0]],['m2',"Nouvelle offre de stage ou d'emploi",[0,1,0]]]]];
    body = `<div class="u-grid u-3-2"><section class="panel"><div class="tbl"><table class="table notif-mx"><thead><tr><th style="text-transform:none;letter-spacing:0;font-size:17px;color:var(--fg);font-family:var(--f-display);font-weight:700;background:var(--surface)">Je veux être prévenu·e</th>${['Application','E-mail','SMS'].map(c=>`<th class="text-center" style="background:var(--surface);text-transform:none;letter-spacing:0;font-size:14px">${c}</th>`).join('')}</tr></thead><tbody>${rows.map(([g,L])=>`<tr class="grp"><td colspan="4" class="small-caps">${g}</td></tr>${L.map(([k,l,d])=>`<tr><td>${l}</td>${d.map((v,j)=>{ const on = P[k+j]!=null ? P[k+j] : v; return `<td class="text-center"><input class="form-check-input" type="checkbox" ${on?'checked':''} data-chg="u-np" data-k="${k+j}" aria-label="${l} — ${['application','e-mail','SMS'][j]}"></td>`; }).join('')}</tr>`).join('')}`).join('')}</tbody></table></div></section>
    <div class="stack">${uCard('Heures calmes', `<p class="small muted">Aucune notification sonore pendant cette plage, sauf les rappels de séance.</p><div class="row g-2"><div class="col-6"><label class="form-label" for="qh1">De</label><input class="form-control" type="time" id="qh1" value="22:00"></div><div class="col-6"><label class="form-label" for="qh2">À</label><input class="form-control" type="time" id="qh2" value="07:00"></div></div>`)}
    ${uCard('Numéro pour les SMS', `<div class="fw-sb" style="font-size:17px">${esc(s.phone)}</div><button class="link-u mt-2" data-act="u-ptab" data-k="info">Modifier dans mes informations</button>`)}<button class="btn btn-primary w-100" data-act="saved" data-m="Préférences de notification enregistrées.">Enregistrer mes préférences</button></div></div>`; }
  if (tab==='secu') { S.st.devices = S.st.devices || [['fa-display','Ordinateur · navigateur Chrome','Cet appareil · Abidjan',1],['fa-mobile-screen','Téléphone · application MY EVC','Actif il y a 2 heures · Abidjan',0],['fa-mobile-screen','Tablette · navigateur Safari','Actif le 12 octobre · Bouaké',0]];
    body = `<div class="u-grid u-1-1"><form class="panel card-pad" data-submit="u-pwd" novalidate><h2 class="h3 mb-3" style="font-size:21px">Changer mon mot de passe</h2><label class="form-label" for="pw-old">Mot de passe actuel</label><input class="form-control mb-3" type="password" id="pw-old" required><label class="form-label" for="pw-new">Nouveau mot de passe</label><input class="form-control" type="password" id="pw-new" required minlength="8" data-inp="u-pwstr"><div class="pw-meter mt-2" id="pw-meter"><i></i><i></i><i></i><i></i></div><div class="small fw-sb mt-1" id="pw-lbl">&nbsp;</div><ul class="pw-rules" id="pw-rules"></ul><label class="form-label mt-2" for="pw-cf">Confirmer le nouveau mot de passe</label><input class="form-control" type="password" id="pw-cf" required><div class="invalid-feedback" id="pw-cf-msg">Confirmez le mot de passe.</div><button class="btn btn-primary mt-4" type="submit">Mettre à jour</button></form>
    <div class="stack"><section class="panel card-pad d-flex gap-3 align-items-start"><div class="flex-grow-1"><h3 class="h3 mb-1" style="font-size:19px">Validation en deux étapes</h3><p class="small muted mb-0">Un code par SMS est demandé lors d'une connexion depuis un nouvel appareil.</p></div><label class="d-flex align-items-center gap-2 fw-sb"><input class="form-check-input mt-0" type="checkbox" checked data-chg="mfa-toggle">Activée</label></section>
    ${uCard('Appareils connectés', S.st.devices.map((d,i)=>`<div class="d-flex align-items-center gap-3 py-2 border-bottom-soft"><span class="nsq" style="width:40px;height:40px;flex-basis:40px"><i class="fa-solid ${d[0]}"></i></span><div class="lr-m"><div class="fw-sb small">${d[1]}</div><div class="small ${d[3]?'tx-ok':'muted'}">${d[2]}</div></div>${d[3]?'':`<button class="btn btn-danger-line btn-sm" data-act="u-dev-out" data-i="${i}">Déconnecter</button>`}</div>`).join(''))}
    ${uCard('Mes données personnelles', `<p class="small muted">Téléchargez une copie de vos informations, notes et documents.</p><button class="link-u" data-act="saved" data-m="Demande enregistrée : l'export vous sera envoyé par e-mail sous 48 h.">Demander l'export de mes données</button>`)}</div></div>`; }
  return `${head}${mobile}<div class="mt-4">${tabs}</div>${body}`;
}, () => { if ((S.ui.ptab||'info')==='secu') INP['u-pwstr']($('#pw-new')); });
Object.assign(VIEWS['e-profil'], {crumb:() => `Espace étudiant <span class="sep">›</span> Profil${S.ui.ptab&&S.ui.ptab!=='info'?` <span class="sep">›</span> ${({parcours:'Parcours',docs:'Documents',pay:'Paiements',notif:'Notifications',secu:'Sécurité'})[S.ui.ptab]}`:''}`});
VIEWS['e-parametres'].render = () => { S.ui.ptab = S.ui.ptab==='secu' ? 'secu' : 'notif'; return VIEWS['e-profil'].render(); }; VIEWS['e-parametres'].parent = 'e-profil';
ACT['u-prof-save'] = () => { const s = S.st.student; s.last = $('#pf-last').value.trim()||s.last; s.first = $('#pf-first').value.trim()||s.first; s.email = $('#pc-mail').value; s.phone = $('#pc-tel').value; s.city = $('#pc-city').value; s.emergency = $('#pf-urg').value; rerender(); toast('Informations enregistrées.'); };
ACT['u-reset'] = () => { rerender(); toast('Modifications annulées.','info'); };
INP['u-pref'] = el => { S.st.prefs[el.dataset.k] = el.checked; toast('Préférence enregistrée.','info'); };
INP['u-np'] = el => { S.st.nprefs[el.dataset.k] = el.checked ? 1 : 0; };
INP['u-doc-add'] = el => { const n = fileNames(el)[0]; if (!n) return; S.st.mydocs.push([n.replace(/\.[^.]+$/,''), frFile(n), "Envoyé aujourd'hui", 'En vérification']); rerender(); toast('Document envoyé à la scolarité pour vérification.'); };
ACT['u-dev-out'] = el => { S.st.devices.splice(+el.dataset.i,1); rerender(); toast('Appareil déconnecté.'); };
INP['u-pwstr'] = el => { if (!el) return; const v = el.value, rules = [[v.length>=8,'Au moins 8 caractères'],[/[a-z]/.test(v)&&/[A-Z]/.test(v),'Une majuscule et une minuscule'],[/\d/.test(v),'Au moins un chiffre'],[/[^A-Za-z0-9]/.test(v),'Un caractère spécial (conseillé)']], n = rules.filter(r=>r[0]).length;
  const m = $('#pw-meter'); if (m) [...m.children].forEach((x,i)=>x.className = i<n ? (n>=3?'ok':n===2?'warn':'bad') : '');
  const l = $('#pw-lbl'); if (l) { l.textContent = v ? ['Trop faible','Faible','Moyen','Mot de passe solide','Excellent'][n] : ' '; l.className = 'small fw-sb mt-1 ' + (n>=3?'tx-ok':n===2?'tx-warn':'tx-bad'); }
  const r = $('#pw-rules'); if (r) r.innerHTML = rules.map(x=>`<li class="${x[0]?'tx-ok':'muted'}">${x[0]?'✓':'○'} ${x[1]}</li>`).join(''); };
ACT['u-pwd'] = f => { if ($('#pw-new').value !== $('#pw-cf').value) { $('#pw-cf').setCustomValidity('x'); $('#pw-cf-msg').textContent = 'Les deux mots de passe ne correspondent pas.'; f.classList.add('was-validated'); $('#pw-cf').addEventListener('input', () => $('#pw-cf').setCustomValidity(''), {once:true}); return; } f.reset(); f.classList.remove('was-validated'); INP['u-pwstr']($('#pw-new')); toast('Mot de passe modifié. Les autres appareils ont été déconnectés.'); };
ACT['u-ptab'] = el => { if (el.dataset.k==='pay') { go('e-paiements'); return; } S.ui.ptab = el.dataset.k; rerender(); };

/* ----- Notifications ----- */
const U_NCAT = {Séances:['fa-calendar-days','info','Voir la séance','e-seances'], Messages:['fa-message','lav','Répondre','e-messagerie'], Travaux:['fa-file-lines','warn','Voir mon travail','e-todo'], Évaluations:['fa-chart-column','ok','Voir mes évaluations','e-evaluations'], Paiements:['fa-credit-card','c','Payer maintenant','e-paiements'], Projets:['fa-palette','lav','Voir mes projets','e-projets'], Certifications:['fa-award','ok','Voir mon dossier','e-certification'], Communiqués:['fa-bullhorn','c','Lire le communiqué',''], Annonces:['fa-bullhorn','c','En savoir plus','e-projets']};
const uNWhen = d => /instant|min|^Il y a \d+ h|h$/i.test(d) ? 'today' : /^Hier/i.test(d) ? 'hier' : 'tot';
view('e-notifications','etu','Notifications','fa-bell', () => {
  const L = S.st.notifs, k = S.ui.nf || 'all', unread = L.filter(n=>!n.read).length;
  const grp = {all:()=>true, unread:n=>!n.read, cours:n=>['Séances','Annonces','Communiqués'].includes(n.cat), travaux:n=>['Travaux','Évaluations','Projets','Certifications'].includes(n.cat), pay:n=>n.cat==='Paiements', msg:n=>n.cat==='Messages'};
  const list = L.filter(grp[k]);
  const row = n => { const c = U_NCAT[n.cat] || U_NCAT.Annonces, parts = n.t.split(/ : |\. /), title = parts[0].replace(/\.$/,''), text = parts.slice(1).join(' · ').replace(/\.$/,'');
    return `<div class="n-item ${n.read?'':'unread'}" data-act="n-read" data-id="${n.id}" role="button" tabindex="0"><span class="uk-i t-${c[1]}" style="width:40px;height:40px;border-radius:11px;display:grid;place-items:center;flex:0 0 auto"><i class="fa-solid ${c[0]}"></i></span><div class="lr-m"><div class="fw-sb" style="font-size:16px">${esc(title)}</div>${text?`<div class="muted small">${esc(text)}</div>`:''}${n.f?`<div class="mt-1">${fchip(n.f)}</div>`:''}<button class="link-u small mt-2" data-act="n-go" data-id="${n.id}" data-to="${c[3]}">${c[2]}</button></div><div class="text-end flex-shrink-0"><div class="small muted">${esc(n.d)}</div>${n.read?'':'<span class="n-dot"></span>'}</div></div>`; };
  const sec = (key, lab) => { const g = list.filter(n=>uNWhen(n.d)===key); return g.length ? `<div class="small-caps mt-4 mb-2">${lab}</div><section class="panel n-list">${g.map(row).join('')}</section>` : ''; };
  return `<div class="d-flex align-items-center gap-2 flex-wrap"><div class="chips">${[['all','Toutes'],['unread',`Non lues (${unread})`],['cours','Cours'],['travaux','Travaux et évaluations'],['pay','Paiements'],['msg','Messages']].map(([x,l])=>`<button class="chip-filter ${k===x?'on':''}" data-act="u-nf" data-k="${x}">${l}</button>`).join('')}</div><div class="ms-auto d-flex align-items-center gap-3">${unread?`<button class="link-u" data-act="n-all">Tout marquer comme lu</button>`:''}<button class="btn btn-quiet btn-icon" data-act="u-ptab-go" aria-label="Préférences de notification"><i class="fa-solid fa-sliders"></i></button></div></div>
  <div style="max-width:960px">${sec('today',"Aujourd'hui")}${sec('hier','Hier')}${sec('tot','Plus tôt')}${list.length?'':`<div class="mt-4">${uEmpty('Aucune notification','Vous êtes à jour.')}</div>`}</div>`;
});
ACT['n-go'] = (el, e) => { e && e.stopPropagation(); const n = S.st.notifs.find(x=>x.id===el.dataset.id); n.read = true; if (el.dataset.to) go(el.dataset.to); else { rerender(); if (n.body) commOpen(n); } };
ACT['u-ptab-go'] = () => uGo('e-profil', {ptab:'notif'});
